// One-time local setup: creates .env.local with a fresh random session secret (never committed).
import { randomBytes } from "node:crypto";
import { existsSync, writeFileSync, mkdirSync } from "node:fs";

mkdirSync("data", { recursive: true });
if (existsSync(".env.local")) {
  console.log(".env.local already exists. Leaving it alone.");
} else {
  const secret = randomBytes(48).toString("base64url");
  writeFileSync(
    ".env.local",
    [
      "# Local settings. This file is git-ignored. Generated by `npm run setup`.",
      `SESSION_SECRET=${secret}`,
      "DATABASE_URL=file:data/goldledger.db",
      "# Shows the demo accounts on the sign-in page. Turn off for real use.",
      "DEMO_MODE=true",
      "# Optional: a second reader for scale and karat photos. The built-in reader works without it.",
      "# GEMINI_API_KEY=",
      "",
    ].join("\n"),
  );
  console.log("Created .env.local with a new SESSION_SECRET.");
}
console.log("Next: npm run seed   (loads the sample data)   then   npm run dev");
